+///|
+priv struct DiagnosticProtectedValues {
+  values : Array[String]
+  mut visited : Int32
+  mut incomplete : Bool
+}
+
+///|
+fn diagnostic_protected_values(
+  value : Json,
+  result : DiagnosticProtectedValues,
+) -> Unit {
+  if result.visited >= 4096 || result.values.length() >= 512 {
+    result.incomplete = true
+    return
+  }
+  result.visited += 1
+  match value {
+    Json::String(text) if text != "" => {
+      result.values.push(text)
+      for line in text.split("\n") {
+        if line != "" && line.length() < text.length() {
+          if result.values.length() >= 512 {
+            result.incomplete = true
+            return
+          }
+          result.values.push(line.to_owned())
+        }
+        for word in line.split(" ") {
+          for part in word.split("=") {
+            if part == "" || part.length() >= text.length() {
+              continue
+            }
+            if result.values.length() >= 512 {
+              result.incomplete = true
+              return
+            }
+            result.values.push(part.to_owned())
+          }
+        }
+      }
+      let escaped = Json::string(text).stringify()
+      if escaped.length() > 2 {
+        let encoded = escaped[1:escaped.length() - 1].to_owned()
+        if encoded != "" && encoded != text {
+          if result.values.length() >= 512 {
+            result.incomplete = true
+            return
+          }
+          result.values.push(encoded)
+        }
+      }
+    }
+    Json::Array(values) =>
+      for item in values {
+        diagnostic_protected_values(item, result)
+      }
+    Json::Object(values) =>
+      for _, item in values {
