705	// A recording grammar, never a replacement for checkout validation. Excludes
706	// URLs, credential forms, control characters and Git's invalid ref syntax.
707	fn diagnostic_ref(text : String) -> Bool {
708	  text.length() <= 1024 &&
709	  !text.has_prefix("-") &&
710	  !text.contains("..") &&
711	  text
712	  .split("/")
713	  .iter()
714	  .all(part => {
715	    part != "" &&
716	    !part.has_prefix(".") &&
717	    !part.has_suffix(".") &&
718	    !part.has_suffix(".lock")
719	  }) &&
720	  text
721	  .iter()
722	  .all(c => {
723	    (c >= 'a' && c <= 'z') ||
724	    (c >= 'A' && c <= 'Z') ||
725	    (c >= '0' && c <= '9') ||
726	    c == '/' ||
727	    c == '-' ||
728	    c == '_' ||
729	    c == '.'
730	  })
731	}
