287	fn diagnostic_error(
288	  error : Error,
289	  environment? : Map[String, String],
290	) -> String {
291	  let (message, omitted) = match error {
292	    AdapterError(detail) => (detail, false)
293	    InvalidConfig(detail) => (detail, false)
294	    @base64.Malformed(_) => ("Malformed base64 input; input omitted", true)
295	    @utf8.Malformed(_) => ("Malformed UTF-8 input; input omitted", true)
296	    @json.InvalidNumber(position, _) =>
297	      (
298	        "Invalid JSON number at line \{position.line}, column \{position.column}; value omitted",
299	        true,
300	      )
301	    _ => (error.to_string(), false)
302	  }
303	  diagnostic_text(message, environment?, omitted~)
