348	///|
349	priv struct DiagnosticProtectedValues {
350	  values : Array[String]
351	  mut visited : Int32
352	  mut incomplete : Bool
353	}
354	
355	///|
356	fn diagnostic_protected_values(
357	  value : Json,
358	  result : DiagnosticProtectedValues,
359	) -> Unit {
360	  if result.visited >= 4096 || result.values.length() >= 512 {
361	    result.incomplete = true
362	    return
363	  }
364	  result.visited += 1
365	  match value {
366	    Json::String(text) if text != "" => {
367	      result.values.push(text)
368	      for line in text.split("\n") {
369	        if line != "" && line.length() < text.length() {
370	          if result.values.length() >= 512 {
371	            result.incomplete = true
372	            return
373	          }
374	          result.values.push(line.to_owned())
375	        }
376	        for word in line.split(" ") {
377	          for part in word.split("=") {
378	            if part == "" || part.length() >= text.length() {
379	              continue
380	            }
381	            if result.values.length() >= 512 {
382	              result.incomplete = true
383	              return
384	            }
385	            result.values.push(part.to_owned())
386	          }
387	        }
388	      }
389	      let escaped = Json::string(text).stringify()
390	      if escaped.length() > 2 {
391	        let encoded = escaped[1:escaped.length() - 1].to_owned()
392	        if encoded != "" && encoded != text {
393	          if result.values.length() >= 512 {
394	            result.incomplete = true
395	            return
396	          }
397	          result.values.push(encoded)
398	        }
399	      }
400	    }
401	    Json::Array(values) =>
402	      for item in values {
403	        diagnostic_protected_values(item, result)
404	      }
405	    Json::Object(values) =>
406	      for _, item in values {
407	        diagnostic_protected_values(item, result)
408	      }
409	    _ => ()
410	  }
411	}
