413	///|
414	fn diagnostic_output(
415	  output : Bytes,
416	  environment : Map[String, String],
417	  protected_input? : String,
418	  omitted~ : Bool = false,
419	) -> String? {
420	  if output.length() == 0 {
421	    return None
422	  }
423	  let safeguards : DiagnosticProtectedValues = {
424	    values: [],
425	    visited: 0,
426	    incomplete: false,
427	  }
428	  if protected_input is Some(input) {
429	    diagnostic_protected_values(@json.parse(input), safeguards) catch {
430	      _ => safeguards.incomplete = true
431	    }
432	  }
433	  if safeguards.incomplete {
434	    return Some(
435	      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
436	    )
437	  }
438	  let mut limit = if output.length() > 8192 { 8192 } else { output.length() }
439	  let incomplete = omitted || limit < output.length()
440	  if incomplete && output[limit - 1] != b'\n' {
441	    while limit > 0 && output[limit - 1] != b'\n' {
442	      limit -= 1
443	    }
444	    if limit == 0 {
445	      return Some(
446	        "Error output omitted because the final line was incomplete\n[error details incomplete or truncated]",
447	      )
448	    }
449	  }
450	  Some(
451	    diagnostic_text(
452	      @utf8.decode_lossy(output[:limit]),
453	      environment~,
454	      omitted=incomplete,
455	      protected_values=safeguards.values,
456	    ),
457	  )
458	}
