484	///|
485	async fn diagnostic_process_output(
486	  program : String,
487	  args : Array[String],
488	  environment~ : Map[String, String],
489	  cwd? : StringView,
490	  stdin? : &@process.ProcessInput,
491	  stdout_limit~ : Int32,
492	  stderr_limit~ : Int32,
493	) -> (Int32, Bytes, Bool, Bytes, Bool) {
494	  let (out, stdout) = @process.read_from_process()
495	  defer out.close()
496	  let (err, stderr) = @process.read_from_process()
497	  defer err.close()
498	  @async.with_task_group(async fn(group) {
499	    let child = @process.spawn(
500	      group,
501	      program,
502	      args,
503	      extra_env=environment,
504	      inherit_env=false,
505	      cwd?,
506	      stdin?,
507	      stdout~,
508	      stderr~,
509	    )
510	    let output = group.spawn(async fn() {
511	      diagnostic_capture(out, stdout_limit)
512	    })
513	    let errors = group.spawn(async fn() {
514	      diagnostic_capture(err, stderr_limit)
515	    })
516	    let status = child.wait()
517	    let (output, output_truncated) = output.wait()
518	    let (errors, errors_truncated) = errors.wait()
519	    (status, output, output_truncated, errors, errors_truncated)
520	  })
521	}
