   306	///|
   307	fn diagnostic_text(
   308	  message : String,
   309	  environment? : Map[String, String],
   310	  omitted~ : Bool = false,
   311	  protected_values? : Array[String],
   312	) -> String {
   313	  let progress = Progress::new("diagnostic-error", environment?)
   314	  if protected_values is Some(values) {
   315	    for value in values {
   316	      if value != "" {
   317	        progress.secrets.push(value)
   318	      }
   319	    }
   320	    progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
   321	  }
   322	  let lines = []
   323	  let mut incomplete = omitted
   324	  for line in message.split("\n") {
   325	    if lines.length() == 8 {
   326	      incomplete = true
   327	      break
   328	    }
   329	    if line.length() > 8192 {
   330	      incomplete = true
   331	      lines.push("[oversized error line omitted]")
   332	      continue
   333	    }
   334	    match progress.safe_message(line.to_owned()) {
   335	      Some(safe) => lines.push(safe)
   336	      None => {
   337	        incomplete = true
   338	        lines.push("[unavailable]")
   339	      }
   340	    }
   341	  }
   342	  if incomplete || progress.details_truncated {
   343	    lines.push("[error details incomplete or truncated]")
   344	  }
   345	  lines.join("\n")
   346	}
