   460	///|
   461	async fn diagnostic_capture(
   462	  reader : @process.ReadFromProcess,
   463	  limit : Int32,
   464	) -> (Bytes, Bool) {
   465	  let output = @buffer.Buffer(size_hint=if limit < 4096 { limit } else { 4096 })
   466	  let mut truncated = false
   467	  while reader.read_some(max_len=4096) is Some(chunk) {
   468	    let remaining = limit - output.length()
   469	    let count = if chunk.length() < remaining {
   470	      chunk.length()
   471	    } else {
   472	      remaining
   473	    }
   474	    if count > 0 {
   475	      output.write_bytes(chunk[:count])
   476	    }
   477	    if count < chunk.length() {
   478	      truncated = true
   479	    }
   480	  }
   481	  (output.to_bytes(), truncated)
   482	}
