   664	///|
   665	priv enum DiagnosticValueKind {
   666	  Identity
   667	  Workspace
   668	  RefName
   669	  Commit
   670	}
   671	
   672	///|
   673	fn diagnostic_value(value : String?, kind : DiagnosticValueKind) -> Json {
   674	  match value {
   675	    None => { "state": "unset" }
   676	    Some("") => { "state": "empty" }
   677	    Some(text) => {
   678	      let valid = match kind {
   679	        Commit => valid_commit(text)
   680	        Workspace => valid_workspace_id(text)
   681	        Identity => text.length() <= 128 && valid_context(text)
   682	        RefName => diagnostic_ref(text)
   683	      }
   684	      let credential_form = text
   685	        .split("/")
   686	        .iter()
   687	        .any(part => {
   688	          [
   689	            "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "glpat-", "sk-",
   690	            "eyJ",
   691	          ]
   692	          .iter()
   693	          .any(prefix => part.has_prefix(prefix))
   694	        })
   695	      if valid && !credential_form {
   696	        { "state": "valid", "value": text }
   697	      } else {
   698	        { "state": "invalid" }
   699	      }
   700	    }
   701	  }
   702	}
