236	async fn Progress::status(self : Progress, event : Json) -> Unit {
237	  guard field(event, "phase") is Some(Json::String(phase)) &&
238	    phase_label(phase) is Some(label) &&
239	    field(event, "state") is Some(Json::String(state)) &&
240	    ["started", "succeeded", "failed", "skipped"].contains(state) else {
241	    return
242	  }
243	  if self.phase_count < 128 {
244	    self.phase_count += 1
245	    save_diagnostic(
246	      self.stage,
247	      state,
248	      phase~,
249	      error_type?=if state == "failed" { Some("backend_phase") } else { None },
250	      recording=self.recording,
251	    )
252	  } else if self.phase_count == 128 {
253	    self.phase_count += 1
254	    save_diagnostic(
255	      self.stage,
256	      "diagnostics-truncated",
257	      error_type="phase_limit",
258	      recording=self.recording,
259	    )
260	  }
261	  let key = ["pipeline", "operationId", "phase", "step"]
262	    .map(name => field(event, name).unwrap_or(Json::null()).stringify())
263	    .join(":")
264	  if state == "started" {
265	    if self.operations.length() >= 256 {
266	      self.operations.clear()
267	    }
268	    self.operations.set(key, @env.now())
269	    progress_message(label + ": running…")
270	  } else {
271	    let duration = match field(event, "durationMs") {
272	      Some(Json::Number(value, ..)) if value >= 0 && value < 864000000 =>
273	        Some(seconds(value.to_uint64()))
274	      _ => self.operations.get(key).map(start => seconds(@env.now() - start))
275	    }
276	    self.operations.remove(key)
277	    let timing = duration.map(value => value + ", ").unwrap_or("") +
278	      "elapsed " +
279	      seconds(@env.now() - progress_started)
280	    progress_message(
281	      label +
282	      ": " +
283	      (if state == "succeeded" { "done" } else { state }) +
284	      " (" +
285	      timing +
286	      ")",
287	    )
288	  }
289	}
