   201	///|
   202	fn Progress::remember(
   203	  self : Progress,
   204	  message : String,
   205	  warning~ : Bool,
   206	) -> Unit {
   207	  let lines = if warning { self.failures } else { self.recent }
   208	  if lines.last() == Some(message) {
   209	    return
   210	  }
   211	  if lines.length() == 8 {
   212	    ignore(lines.remove(0))
   213	    self.details_truncated = true
   214	  }
   215	  lines.push(message)
   216	}
   217	
   218	///|
   219	fn Progress::failure_detail(self : Progress) -> String {
   220	  let lines = self.failures +
   221	    self.recent.filter(line => !self.failures.contains(line))
   222	  let detail = if lines.is_empty() {
   223	    "no readable error message from subprocess"
   224	  } else {
   225	    lines.join("\n")
   226	  }
   227	  detail +
   228	  (if self.details_truncated {
   229	    "\n[error details incomplete or truncated]"
   230	  } else {
   231	    ""
   232	  })
   233	}
