   291	///|
   292	fn classic_build_step(text : String) -> Bool {
   293	  guard text.has_prefix("Step ") &&
   294	    text[5:].split_once("/") is Some((step, rest)) &&
   295	    rest.split_once(" ") is Some((total, detail)) else {
   296	    return false
   297	  }
   298	  step.length() > 0 &&
   299	  total.length() > 0 &&
   300	  step.iter().all(c => c >= '0' && c <= '9') &&
   301	  total.iter().all(c => c >= '0' && c <= '9') &&
   302	  detail.trim().has_prefix(":")
   303	}
