   320	      continue
   321	    }
   322	    if !debug || warning {
   323	      self.remember(safe, warning~)
   324	    }
   325	    if !emit {
   326	      continue
   327	    }
   328	    if safe.has_prefix("#") {
   329	      guard safe.split_once(" ") is Some((id, rest)) &&
   330	        id.length() > 1 &&
   331	        id[1:].iter().all(c => c >= '0' && c <= '9') else {
   332	        continue
   333	      }
   334	      let detail = rest.trim().to_owned()
   335	      guard detail.has_prefix("[") ||
   336	        detail.has_prefix("DONE") ||
   337	        detail.has_prefix("ERROR") ||
   338	        detail.has_prefix("CACHED") else {
   339	        continue
   340	      }
   341	      if detail.has_prefix("ERROR") && debug && !warning {
   342	        self.remember(safe, warning=true)
   343	      }
   344	      if self.builds.get(id.to_owned()) == Some(detail) {
   345	        continue
   346	      }
   347	      if self.builds.length() < 2048 || self.builds.contains(id.to_owned()) {
   348	        self.builds.set(id.to_owned(), detail)
   349	      }
   350	      progress_message("Build " + id.to_owned() + ": " + detail)
   351	    } else if classic_build_step(safe) {
   352	      // Classic RUN output has no prefix. Only its own completion marker
   353	      // ends this mode; phase events on another pipe can arrive ahead of it.
   354	      self.classic_build = true
   355	      progress_message("Build " + safe)
   356	    } else if safe.has_prefix("Successfully built ") ||
   357	      safe.has_prefix("Successfully tagged ") {
   358	      self.classic_build = false
   359	      progress_message("Build: " + safe)
   360	    } else if self.classic_build && !warning {
   361	      continue
   362	    } else if !debug && !safe.has_prefix("{") && !safe.has_prefix("[") {
   363	      progress_message(self.stage + ": " + safe)
   364	    } else if !debug && safe.has_prefix("[credential") {
   365	      progress_message(self.stage + ": " + safe)
   366	    }
   367	  }
   368	}
