   454	  reader : @process.ReadFromProcess,
   455	  capture~ : Bool,
   456	  statuses~ : Bool = false,
   457	  messages~ : Bool = false,
   458	  raw_messages~ : Bool = false,
   459	) -> String {
   460	  let output = @buffer.Buffer(size_hint=4096)
"}}

