+///|
+priv struct DiagnosticProtectedValues {
+  values : Array[String]
+  mut visited : Int32
+  mut incomplete : Bool
+}
+
+///|
+fn diagnostic_protected_values(
+  value : Json,
+  result : DiagnosticProtectedValues,
+) -> Unit {
+  if result.visited >= 4096 || result.values.length() >= 512 {
+    result.incomplete = true
+    return
+  }
+  result.visited += 1
+  match value {
+    Json::String(text) if text != "" => {
+      result.values.push(text)
+      for line in text.split("\n") {
+        if line != "" && line.length() < text.length() {
+          if result.values.length() >= 512 {
+            result.incomplete = true
+            return
+          }
+          result.values.push(line.to_owned())
+        }
+        for word in line.split(" ") {
+          for part in word.split("=") {
+            if part == "" || part.length() >= text.length() {
+              continue
+            }
+            if result.values.length() >= 512 {
+              result.incomplete = true
+              return
+            }
+            result.values.push(part.to_owned())
+          }
+        }
+      }
+      let escaped = Json::string(text).stringify()
+      if escaped.length() > 2 {
+        let encoded = escaped[1:escaped.length() - 1].to_owned()
+        if encoded != "" && encoded != text {
+          if result.values.length() >= 512 {
+            result.incomplete = true
+            return
+          }
+          result.values.push(encoded)
+        }
+      }
+    }
+    Json::Array(values) =>
+      for item in values {
+        diagnostic_protected_values(item, result)
+      }
+    Json::Object(values) =>
+      for _, item in values {
+        diagnostic_protected_values(item, result)
+      }
+    _ => ()
+  }
+}
+
+///|
+fn diagnostic_output(
+  output : Bytes,
+  environment : Map[String, String],
+  protected_input? : String,
+  omitted~ : Bool = false,
+) -> String? {
+  if output.length() == 0 {
+    return None
+  }
+  let safeguards : DiagnosticProtectedValues = {
+    values: [],
+    visited: 0,
+    incomplete: false,
+  }
+  if protected_input is Some(input) {
+    diagnostic_protected_values(@json.parse(input), safeguards) catch {
+      _ => safeguards.incomplete = true
+    }
+  }
+  if safeguards.incomplete {
+    return Some(
+      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
+    )
+  }
+  let mut limit = if output.length() > 8192 { 8192 } else { output.length() }
+  let incomplete = omitted || limit < output.length()
+  if incomplete && output[limit - 1] != b'\n' {
+    while limit > 0 && output[limit - 1] != b'\n' {
+      limit -= 1
+    }
+    if limit == 0 {
+      return Some(
+        "Error output omitted because the final line was incomplete\n[error details incomplete or truncated]",
+      )
+    }
+  }
+  Some(
+    diagnostic_text(
+      @utf8.decode_lossy(output[:limit]),
+      environment~,
+      omitted=incomplete,
+      protected_values=safeguards.values,
+    ),
+  )
+}
+
+///|
+async fn diagnostic_capture(
+  reader : @process.ReadFromProcess,
+  limit : Int32,
+) -> (Bytes, Bool) {
+  let output = @buffer.Buffer(size_hint=if limit < 4096 { limit } else { 4096 })
+  let mut truncated = false
+  while reader.read_some(max_len=4096) is Some(chunk) {
+    let remaining = limit - output.length()
+    let count = if chunk.length() < remaining {
+      chunk.length()
+    } else {
+      remaining
+    }
+    if count > 0 {
+      output.write_bytes(chunk[:count])
+    }
+    if count < chunk.length() {
+      truncated = true
+    }
+  }
+  (output.to_bytes(), truncated)
+}
+
+///|
+async fn diagnostic_process_output(
+  program : String,
+  args : Array[String],
+  environment~ : Map[String, String],
+  cwd? : StringView,
+  stdin? : &@process.ProcessInput,
+  stdout_limit~ : Int32,
+  stderr_limit~ : Int32,
+) -> (Int32, Bytes, Bool, Bytes, Bool) {
+  let (out, stdout) = @process.read_from_process()
+  defer out.close()
+  let (err, stderr) = @process.read_from_process()
+  defer err.close()
+  @async.with_task_group(async fn(group) {
+    let child = @process.spawn(
+      group,
+      program,
+      args,
+      extra_env=environment,
+      inherit_env=false,
+      cwd?,
+      stdin?,
+      stdout~,
+      stderr~,
+    )
+    let output = group.spawn(async fn() {
+      diagnostic_capture(out, stdout_limit)
+    })
+    let errors = group.spawn(async fn() {
+      diagnostic_capture(err, stderr_limit)
+    })
+    let status = child.wait()
+    let (output, output_truncated) = output.wait()
+    let (errors, errors_truncated) = errors.wait()
+    (status, output, output_truncated, errors, errors_truncated)
+  })
+}
+
+///|
+async fn save_command_failure(
+  stage : String,
+  error : Error,
+  recording? : Bool,
+  phase? : String,
+) -> Unit {
+  if !recording.unwrap_or(
+      @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
+    ) {
+    return
+  }
+  let cancelled = @async.is_being_cancelled()
+  let timeout = error is @async.TimeoutError
+  save_diagnostic(
+    stage,
+    if cancelled {
+      "cancelled"
+    } else if timeout {
+      "timeout"
+    } else {
+      "failed"
+    },
+    error_type=if cancelled {
+      "cancelled"
+    } else if timeout {
+      "timeout"
+    } else if error is InvalidConfig(_) {
+      "invalid_config"
+    } else if error is AdapterError(_) {
+      "adapter_error"
+    } else if error is @os_error.OSError(_, ..) {
+      "os_error"
+    } else {
+      "unexpected_error"
+    },
+    os_errno?=match error {
+      @os_error.OSError(code, ..) => Some(code)
+      _ => None
+    },
+    phase?,
+    error_message=diagnostic_error(error),
+    recording?,
+  )
 }

